import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`fleet-savings`,heroTitle:`Cut your fleet costs in minutes`,heroSubtitle:`Perplexity Computer researches current fuel card programs, fleet insurance discounts, GPS tracking tools, and maintenance plans available in your area, then delivers a savings report with specific dollar amounts you could save annually and links to apply for each program.`,hasInputUrl:!1,heroOverlaySteps:[`Reviewing the brief and supporting context to collect the most important inputs`,`Comparing the current situation against useful benchmarks`,`Quantifying tradeoffs, savings, or upside where it matters`,`Shareable analysis with ranked recommendations ready to use`],generatingSteps:[`Reviewing the inputs provided for this workflow to gather the most useful inputs and constraints`,`Designing an agent to benchmark the current state and model the biggest opportunities`,`Configuring prioritization so the highest-value recommendations rise to the top`,`Packaging the work into a concise report with practical next steps`],featureSectionTitle:`From rough inputs to clearer decisions`,featureCardTitles:[`Connects to your business workflow`,`Outputs your team can use`],featureCardDescriptions:[`Computer breaks the work into focused tasks, spins up specialized agents, and matches each task to the model that fits it best.`,`Docs, Sheets, CRM notes, and planning tools stay in the loop so the work moves straight into the tools your team already uses.`,`Benchmarks. Calculations. Prioritized recommendations. Shareable summary. Computer turns rough inputs into a clear decision-making document.`],capabilitySectionTitle:`Your analyst, on demand`,capabilitySectionSubtitle:`Start the workflow, step away, and come back to a clear report with prioritized next steps.`,capabilityCards:[{title:`Input Analysis`,description:`Computer can review the available context, extract the important variables, and frame the problem in a way that supports better decisions.`},{title:`Benchmark Research`,description:`Computer can compare the current state against useful market data, alternatives, or comparable examples to ground the analysis.`},{title:`Opportunity Modeling`,description:`Computer can quantify likely savings, upside, or tradeoffs where relevant so recommendations are easier to prioritize.`},{title:`Connect Your Tools`,description:`Computer can package the analysis into Docs, Sheets, and planning tools so the results are easy to review and circulate.`},{title:`Priority Ranking`,description:`Computer can rank the strongest recommendations by likely value and effort so the team can move quickly.`},{title:`Monitor Changes`,description:`Computer can rerun the analysis later and flag what changed so the team can adapt without restarting from scratch.`}]});export{t as default};
